'use strict';
const $=id=>document.getElementById(id), session=document.querySelector('meta[name="tig-session"]').content;
const state={projects:[],project:'all',category:'',q:'',offset:0,rows:[],selected:null,tab:'Overview',generation:0,mode:'overview',workState:'',facet:'',initialized:false,returnWork:null,searchScope:'project',searchKind:''};
const fmt=new Intl.NumberFormat();
function bytes(n){if(n==null)return'No selection';if(n<1024)return n+' B';let k=Math.min(4,Math.floor(Math.log(n)/Math.log(1024)));return(n/1024**k).toFixed(k>1?1:0)+' '+['B','KiB','MiB','GiB','TiB'][k];}
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e;}
async function api(path,params={}){const response=await fetch(path+'?'+new URLSearchParams(params),{headers:{'X-Tig-Session':session},cache:'no-store',credentials:'omit'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
function notice(message){$('notice').hidden=!message;$('notice').textContent=message||'';}
function selectedProjects(){return state.projects.filter(p=>state.project==='all'||p.id===state.project);}
function projectLabel(id){return state.projects.find(p=>p.id===id)?.label||id;}
function navButton(label,count,active,click,mark){const b=node('button',active?'active':'');if(mark)b.append(node('span','project-mark',mark));b.append(node('span','',label),node('span','nav-count',fmt.format(count)));b.onclick=click;return b;}
function drawNavigation(){
 document.querySelector('.toolbar').hidden=false;$('work-controls').hidden=false;$('assets').className='asset-grid';$('storage').hidden=!state.projects.some(p=>p.storage_locations);if(state.mode==='coverage'){drawCoverageNavigation();return;}if(state.mode==='objects'){drawObjectNavigation();return;}if(state.mode==='storage'){drawStorageNavigation();return;}
 if(state.mode!=='records'){drawWorkNavigation();return;}$('work-controls').replaceChildren();$('technical').hidden=!currentProject()?.collections.length;
 const stats=document.querySelector('.stats');stats.replaceChildren();[['record-count','technical records'],['selected-count','selected subjects'],['size-count','declared selected bytes per project'],['project-count','projects']].forEach(([id,label])=>{const s=node('div'),n=node('span');n.id=id;s.append(n,node('small','',label));stats.append(s);});
 const projects=$('projects');projects.replaceChildren(navButton('All projects',state.projects.reduce((n,p)=>n+p.records,0),state.project==='all',()=>chooseProject('all'),'◫'));
 state.projects.forEach(p=>projects.append(navButton(p.label,p.records,state.project===p.id,()=>chooseProject(p.id),p.label.slice(0,1))));
 const chosen=selectedProjects(), categories={};chosen.forEach(p=>Object.entries(p.categories).forEach(([k,n])=>categories[k]=(categories[k]||0)+n));
 const target=$('categories');target.replaceChildren(navButton('All categories',Object.values(categories).reduce((a,b)=>a+b,0),!state.category,()=>chooseCategory('')));
 Object.entries(categories).sort((a,b)=>a[0].localeCompare(b[0])).forEach(([k,n])=>target.append(navButton(k,n,state.category===k,()=>chooseCategory(k))));
 $('heading').textContent=state.project==='all'?'All projects':projectLabel(state.project);
 $('record-count').textContent=fmt.format(chosen.reduce((n,p)=>n+p.records,0));$('selected-count').textContent=fmt.format(chosen.reduce((n,p)=>n+p.selected_records,0));$('size-count').textContent=bytes(chosen.reduce((n,p)=>n+p.unique_selected_bytes,0));$('project-count').textContent=chosen.length;
 $('subheading').textContent=state.project==='all'?'Browse your assets, their versions and the sources behind them.':'An exact Git snapshot. Your working files and caches stay unchanged.';
 const snapshots=$('snapshot');snapshots.replaceChildren();snapshots.disabled=state.project==='all';
 if(state.project==='all')snapshots.append(new Option('Select a project for branches',''));
 else{const p=chosen[0];snapshots.append(new Option('Pinned · '+p.commit.slice(0,10),p.commit));p.refs.forEach(([name,commit])=>{if(commit!==p.commit)snapshots.append(new Option(name.replace(/^refs\/(heads|remotes|tags)\//,'' )+' · '+commit.slice(0,8),commit));});}
}
async function chooseProject(id){state.project=id;state.searchKind='';state.category='';state.q='';$('search').value='';state.facet='';const p=currentProject();state.mode=id==='all'?'overview':p?.collections.length?'works':'records';if(state.mode==='works'){state.category=p.collections[0].id;state.workState=p.collections[0].count_state||'';}drawNavigation();await load();}
async function chooseCategory(category){state.category=category;drawNavigation();await load();}
function glyph(icon){return({film:'▷',audio:'♫',image:'▧',document:'▤',folder:'▱',asset:'◇'})[icon]||'◇';}
function card(asset){const b=node('button','asset-card');b.setAttribute('aria-label','Inspect '+asset.title);const top=node('div','card-top');top.append(node('span','glyph',glyph(asset.icon)),node('span','tag',asset.category));const body=node('div','card-body');body.append(node('h3','',asset.title));const meta=node('div','card-meta');meta.append(node('span','',projectLabel(asset.project)),node('span','','·'),node('span','',bytes(asset.selected?.bytes)));body.append(meta);const footer=node('div','card-footer');const status=asset.status.lifecycle||asset.status.selection||asset.status.production_state||(asset.selected?'Selected subject':'Planned');footer.append(node('span','status-dot',status.replaceAll('-',' ')),node('span','',asset.streams+' streams'));body.append(footer);b.append(top,body);b.onclick=()=>inspect(asset);return b;}
async function load(more=false){if(state.mode==='coverage'){await loadCoverage(more);return;}if(state.mode==='objects'){await loadManagedObjects(more);return;}if(state.mode==='storage'){await loadStorage(more);return;}const gen=++state.generation;notice('');if(!more){state.offset=0;state.rows=[];$('assets').replaceChildren(node('div','empty','Reading the pinned catalog…'));}
 syncSearchControls();if(state.q&&state.mode!=='records'&&state.searchScope!=='collection'){await searchCatalog(more);return;}
 if(state.mode==='overview'){loadProjectOverview();return;}if(state.mode==='works'){await loadWorks(more);return;}
 try{const data=await api('/api/assets',{project:state.project,category:state.category,q:state.q,offset:state.offset});if(gen!==state.generation)return;if(Object.entries(data.snapshots).some(([id,commit])=>state.projects.find(p=>p.id===id)?.commit!==commit))throw new Error('Snapshot changed in another view. Refresh before browsing more records.');state.rows.push(...data.items);state.offset=state.rows.length;$('assets').replaceChildren(...state.rows.map(card));if(!state.rows.length)$('assets').append(node('div','empty','No assets match these filters.'));$('category-heading').textContent=state.category||'The collection';$('result-count').textContent=fmt.format(data.total)+' records'+(state.q?' matching your search':'');$('more').hidden=state.offset>=data.total;}catch(e){if(gen===state.generation){notice(e.message);$('assets').replaceChildren(node('div','empty','The selected view could not be loaded.'));}}}
function close(){state.selected=null;$('inspector').hidden=true;$('scrim').hidden=true;}
async function inspect(asset){$('back-work').hidden=true;$('back-work').textContent='← Back to work';state.selected=asset;state.tab='Overview';$('inspector').hidden=false;$('scrim').hidden=false;$('asset-title').textContent=asset.title;$('asset-id').textContent=asset.id;$('asset-badges').replaceChildren(node('span','badge',projectLabel(asset.project)),node('span','badge',asset.category));$('detail').replaceChildren(node('p','muted','Reading this exact asset revision…'));try{const p=state.projects.find(p=>p.id===asset.project);const data=await api('/api/asset',{project:asset.project,id:asset.id,snapshot:p.commit});if(state.selected!==asset)return;state.selected.details=data;drawDetail();}catch(e){$('detail').replaceChildren(node('p','callout',e.message));}}
function section(title){const s=node('section','detail-section');s.append(node('h3','',title));return s;}
function field(container,label,value){const f=node('div','field');f.append(node('label','',label),node('div','value',value));container.append(f);}
function drawDetail(){const asset=state.selected;if(!asset?.details)return;const d=asset.details;const tabs=['Overview','Versions','Dependencies','Deliveries','Storage'];$('tabs').replaceChildren(...tabs.map(t=>{const b=node('button',t===state.tab?'active':'',t);b.onclick=()=>{state.tab=t;drawDetail();};return b;}));const area=$('detail');area.replaceChildren();
 if(state.tab==='Overview'){const s=section('Source & identity');field(s,'Exact Git commit',d.commit);field(s,'Definition',d.definition.id);field(s,'Record hash',d.record.object.sha256);field(s,'Selected subject',asset.selected?asset.selected.sha256:'No selected bytes — planned record');area.append(s);const values=section('Admitted project fields');d.fields.filter(f=>f.section==='source').forEach(f=>field(values,f.label,f.value));if(values.childElementCount===1)values.append(node('p','muted','No authored display fields enrolled for this type.'));area.append(values);const statuses=section('Recorded status');Object.entries(asset.status).forEach(([k,v])=>field(statuses,k.replaceAll('_',' '),v));area.append(statuses);}
 if(state.tab==='Versions'){area.append(node('p','callout','These are the record’s declared streams in their original order. A stream may be a version, evidence or a rendition; it is not automatically an approved output.'));for(const s of d.streams){const e=node('div','stream');e.append(node('strong','',s.slot),node('p','',s.group+' · '+s.role+' · '+bytes(s.object.bytes)),node('div','hash',s.object.sha256));area.append(e);}if(!d.streams.length)area.append(node('p','muted','No streams declared in this revision. Git history remains separate.'));}
 if(state.tab==='Deliveries'){const s=section('Declared delivery fields');d.fields.filter(f=>f.section==='delivery').forEach(f=>field(s,f.label,f.value));if(s.childElementCount===1)s.append(node('p','muted','No delivery-target fields enrolled for this definition.'));area.append(s,node('p','callout','Retained targets and receipts do not prove what a cloud provider contains now. No remote checks or uploads run from this page.'));}
 if(state.tab==='Storage'){const s=section('Selected bytes');field(s,'Declared size',bytes(asset.selected?.bytes));field(s,'Enrolled byte locations',d.storage_locations);s.append(node('p','callout','Availability has not been checked. A verification reads only this named object from enrolled existing stores. It creates no copies and does not hydrate missing bytes.'));const b=node('button','button','Verify selected bytes');b.disabled=!asset.selected||!d.storage_locations;b.onclick=async()=>{b.disabled=true;const result=node('div','verify-result','Verifying the exact hash and length…');s.append(result);try{const v=await api('/api/verify',{project:asset.project,id:asset.id,snapshot:d.commit});result.textContent='Verified in enrolled location '+(v.place_index+1)+' · '+bytes(v.object.bytes)+'. Read protection: '+v.protection+'. Independent backup custody is not asserted.';}catch(e){result.textContent=e.message;}finally{b.disabled=false;}};s.append(b);area.append(s,node('p','muted','Automatic eviction is disabled. This catalog has no move or delete operations.'));}
 if(state.tab==='Dependencies'){const target=node('div','callout','Resolving admitted relationships…');area.append(target);api('/api/dependencies',{project:asset.project,id:asset.id,snapshot:d.commit}).then(v=>{if(state.selected!==asset||state.tab!=='Dependencies')return;target.textContent=v.supported?(v.complete_declared_coverage?'Declared dependency coverage resolved.':'Some declared relationships are unresolved; inspect the gaps below.'):v.message;if(v.supported){for(const edge of v.edges){const s=node('div','stream');s.append(node('strong','',edge.kind),node('p','',edge.from.id+' → '+edge.target.id));area.append(s);}for(const gap of v.gaps)area.append(node('div','stream',gap.reason+' · '+gap.at.id));}}).catch(e=>target.textContent=e.message);}
}
$('close').onclick=close;$('scrim').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&!inspector.hidden){const items=[...inspector.querySelectorAll('button:not(:disabled),a[href],input,select')];if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});$('more').onclick=()=>load(true);let debounce;$('search').addEventListener('input',()=>{clearTimeout(debounce);debounce=setTimeout(()=>{state.q=$('search').value;load();},250);});
$('refresh').onclick=()=>bootstrap();$('snapshot').onchange=async()=>{notice('');$('snapshot').disabled=true;try{await api('/api/snapshot',{project:state.project,commit:$('snapshot').value});close();await bootstrap();}catch(e){notice(e.message);}finally{$('snapshot').disabled=false;}};
async function bootstrap(){try{const data=await api('/api/projects');state.projects=data.projects;if(!state.initialized){state.initialized=true;await chooseProject(data.default_project||'all');return;}drawNavigation();await load();}catch(e){notice(e.message);$('assets').replaceChildren(node('div','empty','Catalog unavailable. Check the local application log.'));}}
$('technical').onclick=async()=>{state.category='';state.facet='';state.q='';$('search').value='';if(state.mode==='records'&&currentProject()?.collections.length){state.mode='works';state.category=currentProject().collections[0].id;state.workState=currentCollection()?.count_state||'';}else{state.mode='records';}drawNavigation();$('technical').textContent=state.mode==='records'?'← Back to works':'Technical records';await load();};
$('storage').onclick=()=>openObjectManager(state.mode==='storage'?globalDisk.project:state.project==='all'?'':state.project);
bootstrap();
$('search-scope').onchange=()=>{state.searchScope=$('search-scope').value;state.searchKind='';load();};
$('search-kind').onchange=()=>{state.searchKind=$('search-kind').value;load();};

$('coverage').onclick=()=>openCoverage(state.project==='all'?'':state.project);
